import React from 'react';
import './CaseVisual.css';

const THEMES={
 rifle:{match:['rifle arsenal'],title:'RIFLE ARSENAL',icon:'AK',accent:'#9f354d',accent2:'#ef6b84'},
 sniper:{match:['sniper arsenal'],title:'SNIPER ARSENAL',icon:'AWP',accent:'#2d6f9a',accent2:'#6fc2ff'},
 pistol:{match:['pistol arsenal'],title:'PISTOL ARSENAL',icon:'DE',accent:'#a36d25',accent2:'#f1c15d'},
 knife:{match:['knife arsenal','knives arsenal'],title:'KNIFE ARSENAL',icon:'✦',accent:'#a87b2b',accent2:'#f3c971'},
 gloves:{match:['gloves arsenal','glove arsenal'],title:'GLOVES ARSENAL',icon:'✋',accent:'#356d92',accent2:'#7ac5ef'}
};
function themeFor(name=''){const n=String(name).toLowerCase(); return Object.values(THEMES).find(t=>t.match.some(m=>n.includes(m)))||null;}
export function isArsenalCase(name=''){return !!themeFor(name);}
export default function CaseVisual({caseData,large=false,splash=false}){const t=themeFor(caseData?.name); if(!t)return null; return <div className={`case-visual ${large?'case-visual-large':''} ${splash?'case-visual-splash':''}`} style={{'--cv-accent':t.accent,'--cv-accent2':t.accent2}}><div className="cv-stars"/><div className="cv-halo"/><div className="cv-floor"/><div className="cv-crate"><div className="cv-lid"/><div className="cv-body"><div className="cv-corner cv-corner-tl"/><div className="cv-corner cv-corner-tr"/><div className="cv-corner cv-corner-bl"/><div className="cv-corner cv-corner-br"/><div className="cv-panel"><b>{t.icon}</b><span>WELLCASE</span><em>{t.title}</em></div><div className="cv-lock cv-lock-left"/><div className="cv-lock cv-lock-right"/></div></div><div className="cv-caption">{t.title}</div></div>}
